import type { ComponentType, ReactNode } from 'react'
import type { 事件名类型 } from '@/事件'

// ── 状态 ──────────────────────────────────────────────
// 框架态：与心法配置无关，始终存在
export type 框架态 = '待机' | '拖拽中' | '隐藏'
// 业务态：由配置数据驱动，可选
// 「点击收尾」：关闭问答列表气泡时的收尾状态，播完单次动画自动回「待机」；
// 仅当配置了 状态资源.点击收尾 时才会进入，未配置时关闭气泡直接回「待机」（行为不变）。
export type 业务态 = '主动交互' | '点击交互' | '问答交互' | '点击收尾'
export type 桌宠状态 = 框架态 | 业务态
export type 拖拽方向 = '左' | '右'

// 懒加载组件：复杂内容用 import() 引入，配置里只写函数引用，不写 JSX
export type 懒加载组件 = () => Promise<{ default: ComponentType<any> }>

// ── 尺寸：数字=像素；字符串（如 '30%'）=屏幕宽度百分比；比例=高/宽 ──
export interface 桌宠尺寸 {
  宽?: number | string
  高?: number | string
  // 高 = 宽 × 比例；设置后无需再填高
  比例?: number
}

// ── 资源（CDN url 或 本地 import() 产物，框架无差别处理）──
export interface 桌宠资源 {
  资源: string
  类型?: 'gif' | 'png' | 'webp' | '序列帧'
  序列帧?: { 帧: string[]; 间隔毫秒: number; 循环?: boolean }
  // 非循环动画时长，播完自动回退
  单次时长毫秒?: number
  // 动画结束回退到哪个状态，默认 '待机'
  回退状态?: 桌宠状态
  // 覆盖全局尺寸，设置后以资源自身尺寸为准
  尺寸?: 桌宠尺寸
}

export interface 拖拽动画资源 {
  提起: 桌宠资源 & { 单次时长毫秒: number }
  待机: 桌宠资源 & { 消息?: string; 延迟消息?: { 等待毫秒: number; 文本: string }[] }
  放下: 桌宠资源 & { 单次时长毫秒: number }
  恢复: 桌宠资源
}

// ── 主动交互消息（定时随机/进入后延迟，加权）────────────
export interface 主动交互消息 {
  文本: string
  权重?: number
  内容组件?: 懒加载组件
}

// ── 问题行为 ──────────────────────────────────────────
export type 问题行为 =
  | { 类型: '弹窗'; 标题?: string; 内容?: ReactNode; 内容组件?: 懒加载组件 }
  | { 类型: '跳转'; 链接: string; 新窗口?: boolean }
  | { 类型: '自定义'; 名称: string; 参数?: any }

export type 问题分组 = '入门' | '玩法' | '配装' | '排错' | '进阶' | '维护'

export interface 经典问题 {
  标题: string
  所属心法?: string
  回答方式?: '气泡'
  关键词?: string[]
  行为: 问题行为
  分组?: 问题分组
  排序?: number
}

// ── 事件响应：事件 → 消息 + 可选行为 ────────────────────
export interface 事件响应 {
  事件: 事件名类型
  消息?: string
  行为?: 问题行为
  冷却秒?: number
}

// ── 桌宠配置 ──────────────────────────────────────────
export interface 桌宠配置 {
  名称: string
  启用?: boolean

  // 必须：待机资源（兜底基准）
  待机资源: 桌宠资源

  // 可选状态资源，缺省走回退链：本状态资源 → 待机资源
  状态资源?: Partial<Record<桌宠状态, 桌宠资源>>

  // 拖拽中的方向资源；未配置时回退到状态资源
  拖拽方向资源?: Partial<Record<拖拽方向, 桌宠资源>>

  拖拽动画?: { 常规: 拖拽动画资源; 问答: 拖拽动画资源 }

  // 可选：主动交互（消息集非空才启用该状态）
  主动交互?: {
    消息集: 主动交互消息[]
    资源?: 桌宠资源
    进入后延迟秒?: number | [number, number]
    定时随机间隔秒?: [number, number]
    // 是否合并全局默认主动交互消息，默认 true；设为 false 时只使用自身消息集
    继承全局消息?: boolean
  }

  // 可选：事件响应
  事件响应?: 事件响应[]

  // 可选：点击/问答交互（问题集非空或继承全局问题集才启用）
  点击交互?: {
    经典问题集?: 经典问题[]
    继承全局问题集?: boolean
    资源?: 桌宠资源
  }

  尺寸?: 桌宠尺寸
  默认位置?: { x?: number; y?: number }
  气泡?: { 宽?: number; 主题色?: string }
}
